#[derive(Debug, Clone, PartialEq, Default)]
pub struct Marker {
    /// `MRKB`, required.
    pub begin: Option<Sub<Empty>>,
    /// `MRKD`, optional.
    pub value: Option<Sub<u32>>,
}

impl Marker {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"MRKB",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"MRKD",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.begin, subs, *index, "Marker.MRKB", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.value, subs, *index, "Marker.MRKD", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"MRKB", self.begin.as_ref());
        emit(out, *b"MRKD", self.value.as_ref());
    }
}

impl Visit for Marker {}

