#[derive(Debug, Clone, PartialEq, Default)]
pub struct VvvvRecord {
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// `LNKS`, optional.
    pub links: Option<Sub<VvvvLinks>>,
    /// Group `Slot`, repeated.
    pub slot: Vec<VvvvSlot>,
    /// `LAST`, optional.
    pub last: Option<Sub<VvvvLast>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl VvvvRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LNKS",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: VvvvSlot::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"LAST",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.name, subs, *index, "VVVV.FULL", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.links, subs, *index, "VVVV.LNKS", ctx, extra)
                }
                Hit::Group { member: 2, hits } => {
                    let mut group = VvvvSlot::default();
                    group.fill(hits, subs, ctx, extra);
                    self.slot.push(group);
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.last, subs, *index, "VVVV.LAST", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"FULL", self.name.as_ref());
        emit(out, *b"LNKS", self.links.as_ref());
        for group in &self.slot {
            group.emit(out);
        }
        emit(out, *b"LAST", self.last.as_ref());
    }
}

impl Visit for VvvvRecord {
    fn visit_form_ids<'a>(&'a self, _path: &'static str, out: &mut FormIds<'a>) {
        visit_form_ids(&self.links, "VVVV.LNKS", out);
        visit_form_ids(&self.slot, "VVVV.Slot", out);
        visit_form_ids(&self.last, "VVVV.LAST", out);
    }

    fn visit_form_ids_mut<'a>(&'a mut self, _path: &'static str, out: &mut FormIdsMut<'a>) {
        visit_form_ids_mut(&mut self.links, "VVVV.LNKS", out);
        visit_form_ids_mut(&mut self.slot, "VVVV.Slot", out);
        visit_form_ids_mut(&mut self.last, "VVVV.LAST", out);
    }

    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.name, "VVVV.FULL", out);
        visit_lstrings(&self.slot, "VVVV.Slot", out);
        visit_lstrings(&self.last, "VVVV.LAST", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.name, "VVVV.FULL", out);
        visit_lstrings_mut(&mut self.slot, "VVVV.Slot", out);
        visit_lstrings_mut(&mut self.last, "VVVV.LAST", out);
    }
}

impl VvvvRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"VVVV";

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at
    /// the indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("VVVV", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("VVVV", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("VVVV", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("VVVV", &mut out);
        out
    }
}

