#[derive(Debug, Clone, PartialEq, Default)]
pub struct YyyyRecord {
    /// Group `Head`, required.
    pub head: Option<YyyyHead>,
    /// `SCAL`, optional.
    pub scale: Option<Sub<f32>>,
    /// `WIDE`, optional.
    pub mask: Option<Sub<YyyyMask>>,
    /// `SIGN`, optional.
    pub signed: Option<Sub<YyyySigned>>,
    /// Group `Opt`, optional.
    pub opt: Option<YyyyOpt>,
    /// `GATE`, optional.
    pub gated: Option<Sub<YyyyGated>>,
    /// `GRST`, optional.
    pub gated_rest: Option<Sub<YyyyGatedRest>>,
    /// `PNTS`, optional.
    pub points: Option<Sub<YyyyPoints>>,
    /// `LIST`, optional.
    pub list: Option<Sub<YyyyList>>,
    /// `REFP`, optional.
    pub anchor: Option<Sub<Point>>,
    /// Group `Marker`, repeated.
    pub marker: Vec<Marker>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl YyyyRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Group {
            card: Card::Required,
            members: YyyyHead::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"SCAL",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"WIDE",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"SIGN",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Optional,
            members: YyyyOpt::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"GATE",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"GRST",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"PNTS",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"LIST",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"REFP",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: Marker::MEMBERS,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Group { member: 0, hits } if self.head.is_none() => {
                    let mut group = YyyyHead::default();
                    group.fill(hits, subs, ctx, extra);
                    self.head = Some(group);
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.scale, subs, *index, "YYYY.SCAL", ctx, extra)
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.mask, subs, *index, "YYYY.WIDE", ctx, extra)
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.signed, subs, *index, "YYYY.SIGN", ctx, extra)
                }
                Hit::Group { member: 4, hits } if self.opt.is_none() => {
                    let mut group = YyyyOpt::default();
                    group.fill(hits, subs, ctx, extra);
                    self.opt = Some(group);
                }
                Hit::Sub { member: 5, index } => {
                    put(&mut self.gated, subs, *index, "YYYY.GATE", ctx, extra)
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.gated_rest, subs, *index, "YYYY.GRST", ctx, extra)
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.points, subs, *index, "YYYY.PNTS", ctx, extra)
                }
                Hit::Sub { member: 8, index } => {
                    put(&mut self.list, subs, *index, "YYYY.LIST", ctx, extra)
                }
                Hit::Sub { member: 9, index } => {
                    put(&mut self.anchor, subs, *index, "YYYY.REFP", ctx, extra)
                }
                Hit::Group { member: 10, hits } => {
                    let mut group = Marker::default();
                    group.fill(hits, subs, ctx, extra);
                    self.marker.push(group);
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        if let Some(group) = &self.head {
            group.emit(out);
        }
        emit(out, *b"SCAL", self.scale.as_ref());
        emit(out, *b"WIDE", self.mask.as_ref());
        emit(out, *b"SIGN", self.signed.as_ref());
        if let Some(group) = &self.opt {
            group.emit(out);
        }
        emit(out, *b"GATE", self.gated.as_ref());
        emit(out, *b"GRST", self.gated_rest.as_ref());
        emit(out, *b"PNTS", self.points.as_ref());
        emit(out, *b"LIST", self.list.as_ref());
        emit(out, *b"REFP", self.anchor.as_ref());
        for group in &self.marker {
            group.emit(out);
        }
    }
}

impl Visit for YyyyRecord {
    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.opt, "YYYY.Opt", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.opt, "YYYY.Opt", out);
    }
}

impl YyyyRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"YYYY";

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at
    /// the indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("YYYY", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("YYYY", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("YYYY", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("YYYY", &mut out);
        out
    }
}

